  const p = $('Normalize input').item.json.platform.toLowerCase();
  const o = $('Write Agent').item.json.output;
  if (p !== 'x') return p === 'linkedin' ? 120 : 100;
  const tags = (o.hashtags || []).join(' ');
  return Math.max(40, 270 - o.content.length - tags.length - 4);
})() }}

